import{bV as e,aL as a,u as i,G as n}from"./chunks/framework.BfzMay2U.js";const u=JSON.parse('{"title":"Go主机安全面试：Linux SSH authorized_keys后门检测","description":"","frontmatter":{"title":"Go主机安全面试：Linux SSH authorized_keys后门检测","date":"2026-08-06T17:11:54.000Z","categories":["Interview"],"tags":["go","interview","security","hids","edr","linux","ssh"]},"headers":[],"relativePath":"interview/go-hids-linux-ssh-authorized-keys-backdoor-detection.md","filePath":"interview/go-hids-linux-ssh-authorized-keys-backdoor-detection.md"}'),t={name:"interview/go-hids-linux-ssh-authorized-keys-backdoor-detection.md"};function l(d,s,p,r,o,h){return a(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="go-主机安全面试-linux-ssh-authorized-keys-后门检测" tabindex="-1">Go 主机安全面试：Linux SSH authorized_keys 后门检测 <a class="header-anchor" href="#go-主机安全面试-linux-ssh-authorized-keys-后门检测" aria-label="Permalink to &quot;Go 主机安全面试：Linux SSH authorized_keys 后门检测&quot;">​</a></h1><p>攻击者拿到 Linux 主机权限后，常见的持久化方式之一是在用户的 <code>~/.ssh/authorized_keys</code> 中写入自己的公钥。这样后续登录会走 SSH 公钥认证，看起来比反弹 Shell、WebShell 或异常进程更“正常”。面试官通常会追问：Go Agent 怎么发现 SSH 公钥被植入？如何区分正常密钥轮换和攻击后门？怎么把文件变化、登录日志和进程链路还原成可解释告警？</p><h2 id="岗位场景" tabindex="-1">岗位场景 <a class="header-anchor" href="#岗位场景" aria-label="Permalink to &quot;岗位场景&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Linux 主机</span></span>
<span class="line"><span>  -&gt; 采集用户 home、authorized_keys、sshd 配置、文件事件和登录日志</span></span>
<span class="line"><span>  -&gt; 标准化账号、key 指纹、文件权限、写入进程、会话来源和认证结果</span></span>
<span class="line"><span>  -&gt; 识别新增陌生公钥、异常 AuthorizedKeysFile、Web 进程写 key、root 免密入口</span></span>
<span class="line"><span>  -&gt; 关联 Web RCE、账号提权、sudo、SSH 登录成功和后续命令执行</span></span>
<span class="line"><span>  -&gt; 输出可解释的 SSH key 持久化告警</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>这类题考的是 Linux SSH 认证链路、文件权限模型、账号体系、登录日志解析、攻击链关联、误报治理和 Go Agent 的轻量采集设计。</p><h2 id="高频面试题" tabindex="-1">高频面试题 <a class="header-anchor" href="#高频面试题" aria-label="Permalink to &quot;高频面试题&quot;">​</a></h2><h3 id="_1-为什么-authorized-keys-是高价值检测点" tabindex="-1">1. 为什么 <code>authorized_keys</code> 是高价值检测点？ <a class="header-anchor" href="#_1-为什么-authorized-keys-是高价值检测点" aria-label="Permalink to &quot;1. 为什么 \`authorized_keys\` 是高价值检测点？&quot;">​</a></h3><p>简洁答案：它直接决定哪些公钥可以登录某个本地账号。攻击者写入自己的公钥后，后续可以绕过密码爆破痕迹，用看似合法的 SSH 公钥认证重新进入主机。</p><p>关键知识点：</p><ul><li>常见路径是 <code>/root/.ssh/authorized_keys</code> 和 <code>/home/&lt;user&gt;/.ssh/authorized_keys</code>。</li><li><code>AuthorizedKeysFile</code> 可以在 <code>sshd_config</code> 中改成其他路径，不能只盯默认文件。</li><li>公钥认证成功后，登录日志通常只体现账号和来源 IP，不一定直接暴露“新增 key”。</li><li>root 账号、运维账号、应用部署账号的 key 变化风险更高。</li></ul><p>Go 落地思路：</p><ul><li>采集层记录文件路径、inode、mode、uid、gid、mtime、hash 和解析出的 key 指纹。</li><li>检测层比较前后快照，输出新增、删除、替换和权限漂移。</li><li>事件模型保留写入进程、父进程链、登录会话和来源 IP，避免只报“文件变了”。</li></ul><div class="language-go vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SSHAuthorizedKey</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	User        </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	Path        </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	KeyType     </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	Fingerprint </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	Comment     </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	Options     []</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="_2-authorized-keys-变化应该关注哪些字段" tabindex="-1">2. <code>authorized_keys</code> 变化应该关注哪些字段？ <a class="header-anchor" href="#_2-authorized-keys-变化应该关注哪些字段" aria-label="Permalink to &quot;2. \`authorized_keys\` 变化应该关注哪些字段？&quot;">​</a></h3><p>简洁答案：重点关注新增公钥指纹、key 类型、前置 options、注释、文件权限、属主属组、路径是否偏离基线，以及修改动作来自哪个进程。</p><p>关键知识点：</p><table tabindex="0"><thead><tr><th>关注对象</th><th>典型字段</th><th>风险信号</th></tr></thead><tbody><tr><td>key 内容</td><td>type、base64、comment</td><td>陌生指纹、弱算法、异常注释</td></tr><tr><td>key options</td><td>command、from、environment</td><td>强制命令被改、来源限制被放宽</td></tr><tr><td>文件属性</td><td>mode、uid、gid、inode</td><td>权限过宽、属主异常、文件被替换</td></tr><tr><td>写入来源</td><td>pid、ppid、uid、cmdline</td><td>Web 进程、脚本、临时目录二进制写入</td></tr><tr><td>用户上下文</td><td>user、uid、shell、groups</td><td>root、高权组、服务账号突然可登录</td></tr></tbody></table><p>Go 落地思路：</p><ul><li>不要只保存整文件 hash，要把每条 key 解析成结构化记录，方便解释差异。</li><li>对解析失败的行保留行号和错误原因，异常格式本身也可能是绕过或误配置。</li><li>文件属性变化和 key 内容变化分开建模，避免一个告警里混淆“谁能登录”和“文件是否安全”。</li></ul><h3 id="_3-如何计算-ssh-公钥指纹-为什么不用注释判断" tabindex="-1">3. 如何计算 SSH 公钥指纹，为什么不用注释判断？ <a class="header-anchor" href="#_3-如何计算-ssh-公钥指纹-为什么不用注释判断" aria-label="Permalink to &quot;3. 如何计算 SSH 公钥指纹，为什么不用注释判断？&quot;">​</a></h3><p>简洁答案：注释可以随便伪造，指纹来自公钥主体，更适合做稳定身份标识。检测时应以 key type 和公钥 blob 计算指纹，注释只作为辅助信息。</p><p>关键知识点：</p><ul><li><code>authorized_keys</code> 一行通常包含 options、key type、公钥内容和 comment。</li><li>comment 常见是邮箱、主机名、工具标记，也可能被攻击者伪装成管理员。</li><li>指纹常见算法有 SHA256，展示时要和 <code>ssh-keygen -lf</code> 的结果尽量一致。</li><li><code>ssh-rsa</code> 不一定都是攻击，但在新环境里可以作为弱算法风险信号。</li></ul><p>Go 落地思路：</p><ul><li>优先使用标准库解析 base64 和 hash，不引入新依赖。</li><li>解析器只负责生成结构化 key，弱算法判断放到规则层。</li><li>对同一指纹跨用户、跨主机重复出现的情况做后端关联，不把重逻辑塞进 Agent。</li></ul><div class="language-go vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> keyFingerprint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">raw</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> []</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">byte</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	sum </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sha256.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Sum256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(raw)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	return</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;SHA256:&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> base64.RawStdEncoding.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">EncodeToString</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(sum[:])</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="_4-怎么区分正常密钥轮换和攻击者植入后门" tabindex="-1">4. 怎么区分正常密钥轮换和攻击者植入后门？ <a class="header-anchor" href="#_4-怎么区分正常密钥轮换和攻击者植入后门" aria-label="Permalink to &quot;4. 怎么区分正常密钥轮换和攻击者植入后门？&quot;">​</a></h3><p>简洁答案：看变更来源、变更时间、账号角色、key 是否在资产基线内、是否来自可信发布系统，以及变更后是否出现异常 SSH 登录或命令执行。</p><p>关键知识点：</p><ul><li>正常轮换通常来自堡垒机、配置管理、镜像初始化、CI/CD 或运维账号。</li><li>攻击植入常见链路是 <code>nginx/php-fpm -&gt; sh -&gt; echo &gt;&gt; authorized_keys</code>。</li><li>对 root 写 key、服务账号新增交互 shell、多个账号同时加入同一陌生 key，要提高风险。</li><li>有些客户会批量更新 key，不能把批量变化天然判为攻击。</li></ul><p>Go 落地思路：</p><ul><li>用 <code>reason_codes</code> 表达命中原因，例如 <code>new_key_for_root</code>、<code>web_process_writer</code>、<code>unknown_fingerprint</code>。</li><li>维护小基线：账号到指纹集合、可信写入进程、维护窗口和主机角色。</li><li>把“新增 key”与“随后 SSH 公钥登录成功”放在短窗口内关联，提升告警可信度。</li></ul><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Web RCE 进程链</span></span>
<span class="line"><span>  -&gt; 写入 /root/.ssh/authorized_keys</span></span>
<span class="line"><span>  -&gt; 5 分钟后同一来源网段 SSH 公钥登录成功</span></span>
<span class="line"><span>  -&gt; root 执行 curl 下载脚本</span></span>
<span class="line"><span>  -&gt; 高危 SSH key 持久化告警</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="_5-sshd-config-的哪些配置会影响检测" tabindex="-1">5. <code>sshd_config</code> 的哪些配置会影响检测？ <a class="header-anchor" href="#_5-sshd-config-的哪些配置会影响检测" aria-label="Permalink to &quot;5. \`sshd_config\` 的哪些配置会影响检测？&quot;">​</a></h3><p>简洁答案：<code>AuthorizedKeysFile</code>、<code>PermitRootLogin</code>、<code>PubkeyAuthentication</code>、<code>Match</code> 块和 <code>AllowUsers</code> 等配置都会改变公钥登录边界，检测时要把配置变化纳入证据链。</p><p>关键知识点：</p><ul><li><code>AuthorizedKeysFile</code> 支持多个路径和变量，例如 <code>%h/.ssh/authorized_keys</code>。</li><li><code>Match User</code>、<code>Match Address</code> 可能让部分账号或来源使用不同策略。</li><li><code>PermitRootLogin prohibit-password</code> 仍允许 root 公钥登录。</li><li>攻击者可能把 key 文件路径改到更隐蔽的位置，而不是直接修改默认文件。</li></ul><p>Go 落地思路：</p><ul><li>低频解析 <code>/etc/ssh/sshd_config</code> 和 include 文件，生成有效配置摘要。</li><li>先支持关键字段和 include 路径，不必实现完整 OpenSSH 配置解释器。</li><li>配置变化事件与 key 文件变化事件共享同一条检测时间线。</li></ul><h3 id="_6-文件事件、审计日志和登录日志各自提供什么证据" tabindex="-1">6. 文件事件、审计日志和登录日志各自提供什么证据？ <a class="header-anchor" href="#_6-文件事件、审计日志和登录日志各自提供什么证据" aria-label="Permalink to &quot;6. 文件事件、审计日志和登录日志各自提供什么证据？&quot;">​</a></h3><p>简洁答案：文件事件说明“key 被改了”，审计或进程事件说明“谁改的”，登录日志说明“改完有没有被用来登录”。三者结合才能形成完整闭环。</p><p>关键知识点：</p><table tabindex="0"><thead><tr><th>证据来源</th><th>能回答的问题</th><th>常见局限</th></tr></thead><tbody><tr><td>文件快照</td><td>新增了哪个 key、文件权限如何</td><td>不一定知道写入者</td></tr><tr><td>auditd/fanotify</td><td>谁打开、写入、rename 了文件</td><td>环境可能未开启或丢事件</td></tr><tr><td>进程执行</td><td>是否由 echo、sed、scp、配置管理写入</td><td>需要父子进程链</td></tr><tr><td>auth 日志</td><td>哪个账号从哪里登录成功</td><td>不一定直接给出 key 指纹</td></tr></tbody></table><p>Go 落地思路：</p><ul><li>文件事件只作为触发，最终重新读取文件并生成快照 diff。</li><li>登录日志解析要保留账号、来源 IP、认证方式、时间和 sshd pid。</li><li>检测层用事件时间做窗口关联，处理文件事件和日志事件乱序到达。</li></ul><h3 id="_7-如何降低-authorized-keys-检测误报" tabindex="-1">7. 如何降低 <code>authorized_keys</code> 检测误报？ <a class="header-anchor" href="#_7-如何降低-authorized-keys-检测误报" aria-label="Permalink to &quot;7. 如何降低 \`authorized_keys\` 检测误报？&quot;">​</a></h3><p>简洁答案：不要把“文件变化”直接等价为入侵。要按账号价值、写入来源、key 是否已知、维护窗口、主机角色和后续行为分级。</p><p>关键知识点：</p><ul><li>云初始化、扩缩容、运维平台和部署系统都可能自动写 key。</li><li>开发机、跳板机、生产服务器的 key 变化基线不同。</li><li>只按路径白名单会被绕过，攻击者也会写默认路径。</li><li>降噪应该保留审计事件，低风险变更可以降级而不是丢弃。</li></ul><p>Go 落地思路：</p><ul><li>对可信来源使用多条件匹配：进程路径、签名或 hash、执行用户、父进程和时间窗口。</li><li>对高权账号新增陌生 key 即使在维护窗口也保留中危审计。</li><li>客户反馈误报后用离线 replay 验证规则，不直接扩大白名单。</li></ul><h3 id="_8-agent-采集这类文件时有哪些可靠性和安全注意点" tabindex="-1">8. Agent 采集这类文件时有哪些可靠性和安全注意点？ <a class="header-anchor" href="#_8-agent-采集这类文件时有哪些可靠性和安全注意点" aria-label="Permalink to &quot;8. Agent 采集这类文件时有哪些可靠性和安全注意点？&quot;">​</a></h3><p>简洁答案：关键文件数量有限，适合事件触发加周期快照。重点是避免符号链接绕过、权限不足、读取竞态、路径爆炸和敏感内容泄露。</p><p>关键知识点：</p><ul><li>home 目录可能很多，不能无限递归扫描所有隐藏目录。</li><li><code>authorized_keys</code> 可能被 symlink 到其他位置，需要记录真实路径和 link 信息。</li><li>攻击者可能先写临时文件再 rename，单纯监听 write 可能漏掉最终替换。</li><li>公钥通常不算 secret，但 comment 里可能包含邮箱、机器名或内部标识，上传前要控制字段。</li></ul><p>Go 落地思路：</p><ul><li>从 <code>/etc/passwd</code> 或 NSS 快照获取候选用户，再定位 <code>.ssh</code> 目录。</li><li>对 watch 失败、权限不足和解析失败分别上报健康状态，不影响主链路。</li><li>使用最大用户数、最大文件大小和扫描周期限制资源消耗。</li></ul><h2 id="通俗答案" tabindex="-1">通俗答案 <a class="header-anchor" href="#通俗答案" aria-label="Permalink to &quot;通俗答案&quot;">​</a></h2><p>可以把 <code>authorized_keys</code> 理解成“谁拿着钥匙就能进门”的名单。HIDS/EDR 不能只看名单有没有变，还要回答：</p><ol><li>新钥匙是谁加进去的。</li><li>这把钥匙以前是否属于可信管理员或运维系统。</li><li>它加到了哪个账号，是否是 root 或高权限账号。</li><li>加完以后有没有真的被用于 SSH 登录。</li><li>这次变更前后是否存在 Web RCE、提权、日志清理或异常外联。</li></ol><p>这些问题回答清楚，告警才不是“文件变化提醒”，而是“SSH key 持久化攻击链”。</p><h2 id="go-落地要点" tabindex="-1">Go 落地要点 <a class="header-anchor" href="#go-落地要点" aria-label="Permalink to &quot;Go 落地要点&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>采集层</span></span>
<span class="line"><span>  -&gt; 用户与 home 快照：passwd、home、shell、uid/gid</span></span>
<span class="line"><span>  -&gt; SSH key 文件：authorized_keys、权限、属主、key 指纹</span></span>
<span class="line"><span>  -&gt; 配置文件：sshd_config、include、AuthorizedKeysFile</span></span>
<span class="line"><span>  -&gt; 上下文事件：进程执行、文件写入、登录日志、sudo</span></span>
<span class="line"><span></span></span>
<span class="line"><span>标准化层</span></span>
<span class="line"><span>  -&gt; SSHAuthorizedKey / SSHKeyChangeEvent / SSHLoginEvent</span></span>
<span class="line"><span>  -&gt; 保留 path、line、fingerprint、uid、pid、ppid、session、source_ip</span></span>
<span class="line"><span></span></span>
<span class="line"><span>检测层</span></span>
<span class="line"><span>  -&gt; key diff</span></span>
<span class="line"><span>  -&gt; 高权账号和陌生指纹识别</span></span>
<span class="line"><span>  -&gt; 写入进程与登录行为关联</span></span>
<span class="line"><span>  -&gt; 基线降噪和 reason_codes 输出</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>工程实现上保持 KISS：先把默认路径、关键配置、key 指纹和登录日志串起来，再逐步补 include、Match 块和客户基线。不要一开始就写复杂的 SSH 配置解释器，否则容易在边界条件里消耗大量时间。</p><h2 id="学习要点" tabindex="-1">学习要点 <a class="header-anchor" href="#学习要点" aria-label="Permalink to &quot;学习要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>需要掌握</th></tr></thead><tbody><tr><td>SSH 认证</td><td>公钥认证、authorized_keys、sshd_config、PermitRootLogin</td></tr><tr><td>Linux 文件权限</td><td>mode、uid/gid、home 目录、symlink、rename</td></tr><tr><td>日志解析</td><td>auth.log、secure、Accepted publickey、来源 IP</td></tr><tr><td>攻击链</td><td>Web RCE、提权、写 key、SSH 回连、后续命令</td></tr><tr><td>Go 工程</td><td>文件快照、结构化 diff、滑动窗口、限流、解析容错</td></tr><tr><td>误报治理</td><td>账号基线、可信变更源、维护窗口、reason_codes</td></tr></tbody></table><h2 id="小练习" tabindex="-1">小练习 <a class="header-anchor" href="#小练习" aria-label="Permalink to &quot;小练习&quot;">​</a></h2><ol><li>设计一个 <code>SSHKeyChangeEvent</code>，要求能表达新增 key、删除 key、权限变化和写入进程。</li><li>写一个只依赖标准库的函数，解析 <code>authorized_keys</code> 中的 key type、base64 公钥和 comment。</li><li>给出一条规则：<code>nginx</code> 子进程写入 <code>/root/.ssh/authorized_keys</code> 后 10 分钟内出现 root SSH 公钥登录，如何打分和解释？</li><li>如果客户的配置管理系统每天批量更新 key，你会用哪些字段降噪？</li><li><code>AuthorizedKeysFile</code> 被改到 <code>/var/tmp/.keys/%u</code>，你的采集链路如何发现并扩大监控路径？</li><li>复盘一次误报时，你希望保存哪些原始证据和标准化字段？</li></ol>`,68)])])}const k=e(t,[["render",l]]);export{u as __pageData,k as default};
